(function(window,document){'use strict';const P=['۰','۱','۲','۳','۴','۵','۶','۷','۸','۹'],W=['ش','ی','د','س','چ','پ','ج'],M=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];const toFa=n=>String(n).replace(/\d/g,d=>P[Number(d)]);const toEn=t=>String(t||'').replace(/[۰-۹]/g,d=>'0123456789'['۰۱۲۳۴۵۶۷۸۹'.indexOf(d)]).replace(/\//g,'-');function pad(v){return String(v).padStart(2,'0')}function parseValue(v){const n=toEn(v).trim();const m=n.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})$/);if(!m)return null;return{jy:Number(m[1]),jm:Number(m[2]),jd:Number(m[3])}}function fmt(y,m,d,slash){const s=slash?'/':'-';return [toFa(y),toFa(pad(m)),toFa(pad(d))].join(s)}function jalaliToGregorian(jy,jm,jd){if(window.JalaliDate&&typeof window.JalaliDate.jalaliToGregorian==='function')return window.JalaliDate.jalaliToGregorian(jy,jm,jd);throw new Error('JalaliDate is required')}function gregorianToJalali(gy,gm,gd){if(window.JalaliDate&&typeof window.JalaliDate.gregorianToJalali==='function')return window.JalaliDate.gregorianToJalali(gy,gm,gd);throw new Error('JalaliDate is required')}function toGregorianDate(jy,jm,jd){const g=jalaliToGregorian(jy,jm,jd);return new Date(g[0],g[1]-1,g[2])}function todayJ(){const now=new Date();const j=gregorianToJalali(now.getFullYear(),now.getMonth()+1,now.getDate());return{jy:j[0],jm:j[1],jd:j[2]}}function monthDays(jy,jm){const n=jm===12?{jy:jy+1,jm:1}:{jy,jm:jm+1};const next=toGregorianDate(n.jy,n.jm,1);next.setDate(next.getDate()-1);const j=gregorianToJalali(next.getFullYear(),next.getMonth()+1,next.getDate());return j[2]}function monthMeta(jy,jm){const first=toGregorianDate(jy,jm,1);return{days:monthDays(jy,jm),offset:(first.getDay()+1)%7}}let pop,active,state={jy:0,jm:0,selected:null};function ensure(){if(pop)return;pop=document.createElement('div');pop.className='jdp-popover hidden';pop.innerHTML='<div class="jdp-head"><button type="button" class="jdp-nav" data-jdp-prev>‹</button><div class="jdp-title" data-jdp-title></div><button type="button" class="jdp-nav" data-jdp-next>›</button></div><div class="jdp-weekdays">'+W.map(w=>'<span class="jdp-weekday">'+w+'</span>').join('')+'</div><div class="jdp-grid" data-jdp-grid></div><div class="jdp-actions"><button type="button" class="jdp-action" data-jdp-clear>پاک‌کردن</button><button type="button" class="jdp-action" data-jdp-today>امروز</button></div>';document.body.appendChild(pop);pop.addEventListener('click',e=>{if(e.target.closest('[data-jdp-prev]')){move(-1);return}if(e.target.closest('[data-jdp-next]')){move(1);return}if(e.target.closest('[data-jdp-today]')){const t=todayJ();select(t.jy,t.jm,t.jd);return}if(e.target.closest('[data-jdp-clear]')){if(active)active.value='';hide();return}const d=e.target.closest('[data-jdp-day]');if(d)select(Number(d.dataset.y),Number(d.dataset.m),Number(d.dataset.d));});document.addEventListener('mousedown',e=>{if(pop.classList.contains('hidden'))return;if(active&&(active===e.target||active.contains?.(e.target)))return;if(pop.contains(e.target))return;hide();});window.addEventListener('resize',()=>{if(active&&!pop.classList.contains('hidden'))show(active)});window.addEventListener('scroll',()=>{if(active&&!pop.classList.contains('hidden'))show(active)},true)}function render(){const title=pop.querySelector('[data-jdp-title]');const grid=pop.querySelector('[data-jdp-grid]');const meta=monthMeta(state.jy,state.jm);const t=todayJ();title.textContent=M[state.jm-1]+' '+toFa(state.jy);let html='';for(let i=0;i<meta.offset;i++)html+='<span></span>';for(let day=1;day<=meta.days;day++){const selected=state.selected&&state.selected.jy===state.jy&&state.selected.jm===state.jm&&state.selected.jd===day;const isToday=t.jy===state.jy&&t.jm===state.jm&&t.jd===day;html+='<button type="button" class="jdp-day'+(selected?' is-selected':'')+(isToday?' is-today':'')+'" data-jdp-day data-y="'+state.jy+'" data-m="'+state.jm+'" data-d="'+day+'">'+toFa(day)+'</button>'}grid.innerHTML=html}function move(step){state.jm+=step;if(state.jm>12){state.jm=1;state.jy+=1}if(state.jm<1){state.jm=12;state.jy-=1}render()}function select(jy,jm,jd){if(active){const slash=(active.getAttribute('data-jdp-format')||'').toLowerCase()!=='dash';active.value=fmt(jy,jm,jd,slash);active.dispatchEvent(new Event('change',{bubbles:true}));active.dispatchEvent(new Event('input',{bubbles:true}))}hide()}function show(input){ensure();active=input;input.classList.add('jdp-input-ready');const parsed=parseValue(input.value)||todayJ();state={jy:parsed.jy,jm:parsed.jm,selected:parseValue(input.value)};render();const r=input.getBoundingClientRect();pop.style.top=(window.scrollY+r.bottom+10)+'px';pop.style.left=(window.scrollX+Math.max(16,Math.min(r.left,window.innerWidth-pop.offsetWidth-16)))+'px';pop.classList.remove('hidden')}function hide(){if(pop)pop.classList.add('hidden');active=null}function mount(input){if(input.dataset.jdpMounted==='1')return;input.dataset.jdpMounted='1';input.setAttribute('autocomplete','off');input.addEventListener('focus',()=>show(input));input.addEventListener('click',()=>show(input));input.addEventListener('keydown',e=>{if(e.key==='Escape')hide()})}window.jalaliDatepicker={startWatch:function(opts){const selector=opts&&opts.selector?opts.selector:'[data-jdp]';document.querySelectorAll(selector).forEach(mount)}}})(window,document);
